(220, 'Cosplay in Love', 'cosplay-in-love', '<p><span style=\"color: rgb(75, 79, 86); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">Expo Fiere, in collaborazione con lo staff di Comicspopoli, &egrave; lieta di presentare \"Cosplay in Love\", evento dedicato al mondo del Cosplay e del Comics&amp;Games, dove, in quest\' occasione, l\'amore far&agrave; da sfondo ad un San Valentino(anticipato) alternativo!&nbsp;</span><span style=\"color: rgb(75, 79, 86); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">Oltre al classico contest cosplay, sar&agrave; prevista una gara dedicata interamente alle coppie!&nbsp;</span><span style=\"color: rgb(75, 79, 86); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">Tutto l\'intrattenimento si terr&agrave; al 1 piano nella sala rossa.</span></p>\r\n<p><span style=\"color: rgb(75, 79, 86); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px;\">L\'evento si terr&agrave; presso Ferrara Fiere Congressi in via della Fiera 11 a Ferrara.</span></p>', '2017-02-12', '2026-12-31', 'Ferrara', 5, 140, 8297, 44.8140270, 11.5853860, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, '2025-09-16 10:32:00', '2026-02-05 08:32:30'),
(221, 'Carnival Tour 2017 - Centro Commerciale Roma Est', 'carnival-tour-2017---centro-commerciale-roma-est', '<p>Vi aspettiamo con il nostro Mega Show e animazione insieme alla musica pi&ugrave; bella del passato e del presente rivisitata con Remix &amp; Mash-Up che vi romperanno le orecchie!!!</p>\r\n<p>L\'evento si terr&agrave; presso il Centro Commerciale Roma Est in via Collatina (km 12,800) a Roma.</p>', '2017-02-26', '2026-12-31', 'Roma', 7, 187, 9126, 41.9148230, 12.6618900, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, '2025-09-16 10:32:00', '2026-02-05 08:32:30'),
(222, 'Firenze Comics Day', 'firenze-comics-day', '<p><span style=\"color: rgb(29, 33, 41); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 13px;\">Il 23 marzo 2017 si svolger&agrave; al teatro Obihall il primo Firenze Comics Day organizzato dalla Scuola Internazionale di Comics di Firenze: un\'intera giornata d con workshop, concorsi e idee per scoprire le professioni delle arti visive e digitali.</span></p>\r\n<p><span style=\"color: rgb(29, 33, 41); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 13px;\">L\'evento si terr&agrave; presso l\'Obihall in v</span><span style=\"color: rgba(0, 0, 0, 0.870588); font-family: Roboto, Arial, sans-serif; font-size: 13px;\">ia Fabrizio De Andr&eacute; a Firenze.</span></p>', '2017-03-23', '2026-12-31', 'Firenze', 16, 142, 8627, 43.7665980, 11.2960170, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, '2025-09-16 10:32:00', '2026-02-05 08:32:30');
